27	/**
28	 * The sheet's figures as the screen shows them: each person's claimed and due-total, and the sheet's
29	 * claimed-total and due-total. A change takes them before it alters anything and hands them back after, and
30	 * every figure it moved is written to the audit after the change's own lines. Called within the change's
31	 * transaction.
32	 */
33	@Service
34	public class RollupService {
35	
36	    /** Shown in place of a due-total whose grade has no rate. */
37	    private static final String NO_RATE = "n/a";
38	
39	    /** A person's figures, as the screen shows them. */
40	    public record Figures(String name, String claimed, String dueTotal) {}
41	
42	    /** The sheet's figures at one moment: each person's by id, in the order they were added, and the totals. */
43	    public record Snapshot(Map<Long, Figures> people, String claimedTotal, String dueTotal) {}
44	
45	    /** What a claim's late charge goes by: the sheet's today (none when there is no such sheet) and its late
46	     * percent; and the date its rounding goes by, the policy date or else the sheet's today. */
47	    private record Lateness(LocalDate today, BigDecimal latePct, LocalDate policyDate) {
48	
49	        static Lateness of(Sheet sheet) {
50	            return sheet == null ? new Lateness(null, BigDecimal.ZERO, null)
51	                    : new Lateness(sheet.getToday(), sheet.getLatePct(), sheet.roundingDate());
52	        }
53	
54	        /** How a claim's live figures round, by the date they go by: one before the policy date rounds half up,
55	         * one on or after it half to even. */
56	        RoundingMode rounding(LocalDate roundsBy) {
57	            return policyDate != null && roundsBy.isBefore(policyDate) ? RoundingMode.HALF_UP
58	                    : RoundingMode.HALF_EVEN;
59	        }
60	    }
61	
62	    /** The days in each period an overdue claim gains its late percent for. */
63	    private static final int LATE_PERIOD_DAYS = 30;
64	
65	    private final PersonRepository people;
66	    private final ClaimRepository claims;
67	    private final RateRepository rates;
68	    private final SheetRepository sheets;
69	    private final Audit audit;
70	
71	    public RollupService(PersonRepository people, ClaimRepository claims, RateRepository rates,
72	            SheetRepository sheets, Audit audit) {
73	        this.people = people;
74	        this.claims = claims;
75	        this.rates = rates;
76	        this.sheets = sheets;
77	        this.audit = audit;
78	    }
79	
80	    /** The sheet's figures now; none (an empty sheet's) when there is no such sheet. */
81	    public Snapshot snapshot(String sheetId) {
82	        Lateness late = latenessOf(sheetId);
83	        LocalDate today = late.today();
84	        BigDecimal floor = floorOf(sheetId);
85	        Map<Long, List<Claim>> byPerson = new LinkedHashMap<>();
86	        List<Claim> all = claims.findBySheetIdOrderByIdDesc(sheetId);
87	        for (Claim claim : all) {
88	            byPerson.computeIfAbsent(claim.getPersonId(), k -> new ArrayList<>()).add(claim);
89	        }
90	        Map<String, LocalDate> datesByNumber = datesByNumber(all);
91	        Map<Long, Figures> figures = new LinkedHashMap<>();
92	        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
93	        BigDecimal dueTotal = BigDecimal.ZERO.setScale(2);
94	        Map<String, List<Rate>> byGrade = ratesByGrade(sheetId);
95	        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
96	            List<Claim> counted = byPerson.getOrDefault(person.getId(), List.of()).stream()
97	                    .filter(c -> counts(c, person)).toList();
98	            BigDecimal claimed = BigDecimal.ZERO.setScale(2);
99	            BigDecimal due = BigDecimal.ZERO.setScale(2);
100	            boolean frozen = false;
101	            for (Claim claim : counted) {
102	                claimed = claimed.add(claim.getAmount().setScale(2));
103	                frozen |= keepsFigure(claim);
104	                BigDecimal figure = dueOf(claim, ratesOn(person, claim.getDate(), byGrade), floor, late,
105	                        roundsBy(claim, datesByNumber));
106	                if (figure != null) {
107	                    due = due.add(figure.setScale(2));
108	                }
109	            }
110	            // Like the screen: with no rate in force today and no claim keeping a figure, the due-total is n/a.
111	            boolean rated = rated(person, counted, today, byGrade);
112	            String personDue = rated || frozen ? due.toPlainString() : NO_RATE;
113	            claimedTotal = claimedTotal.add(claimed);
114	            if (rated || frozen) {
115	                dueTotal = dueTotal.add(due);
116	            }
117	            figures.put(person.getId(), new Figures(person.getName(), claimed.toPlainString(), personDue));
118	        }
119	        return new Snapshot(figures, claimedTotal.toPlainString(), dueTotal.toPlainString());
120	    }
121	
122	    /** The due-total of the sheet's claims that count (OPEN and PENDING ones within a hold, unbound, do not) dated from and to, inclusive: the sum of their dues,
123	     * late charges included, n/a ones skipped. */
124	    public BigDecimal dueTotal(String sheetId, LocalDate from, LocalDate to) {
125	        BigDecimal floor = floorOf(sheetId);
126	        Lateness late = latenessOf(sheetId);
127	        Map<String, List<Rate>> byGrade = ratesByGrade(sheetId);
128	        Map<Long, Person> byId = new LinkedHashMap<>();
129	        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
130	            byId.put(person.getId(), person);
131	        }
132	        BigDecimal total = BigDecimal.ZERO.setScale(2);
133	        List<Claim> all = claims.findBySheetIdOrderByIdDesc(sheetId);
134	        Map<String, LocalDate> datesByNumber = datesByNumber(all);
135	        for (Claim claim : all) {
136	            Person person = byId.get(claim.getPersonId());
137	            if (person == null || !counts(claim, person)
138	                    || claim.getDate().isBefore(from) || claim.getDate().isAfter(to)) {
139	                continue;
140	            }
141	            BigDecimal figure = dueOf(claim, ratesOn(person, claim.getDate(), byGrade), floor, late,
142	                    roundsBy(claim, datesByNumber));
143	            if (figure != null) {
144	                total = total.add(figure.setScale(2));
145	            }
146	        }
147	        return total;
148	    }
149	
150	    /**
151	     * Write to the audit, once the change commits, one ROLLUP line for each person whose figures moved since
152	     * {@code before} (a person new since then counts as moved), in the order they were added, then a TOTALS
153	     * line when the sheet's totals moved.
154	     */
155	    public void recordChanges(String user, String sheetId, Snapshot before) {
156	        claims.flush();
157	        Snapshot after = snapshot(sheetId);
158	        String prefix = " sheet=" + sheetId + " by=" + user;
159	        for (Map.Entry<Long, Figures> e : after.people().entrySet()) {
160	            Figures now = e.getValue();
161	            Figures was = before.people().get(e.getKey());
162	            if (was != null && was.claimed().equals(now.claimed()) && was.dueTotal().equals(now.dueTotal())) {
163	                continue;
164	            }
165	            audit.recordOnCommit("ROLLUP" + prefix + " person=" + now.name() + " claimed=" + now.claimed()
166	                    + " due-total=" + now.dueTotal());
167	        }
168	        if (!Objects.equals(before.claimedTotal(), after.claimedTotal())
169	                || !Objects.equals(before.dueTotal(), after.dueTotal())) {
170	            audit.recordOnCommit("TOTALS" + prefix + " claimed-total=" + after.claimedTotal()
171	                    + " due-total=" + after.dueTotal());
172	        }
173	    }
174	
175	    /** The figure a claim has now: what it was settled at, else what its person's last statement bound it to
176	     * (while not PENDING), else what is due at the rate of the grade its person has on its date, raised to the sheet's floor; none
177	     * when that is n/a. */
178	    public BigDecimal figureOf(Claim claim, Person person) {
179	        return figureOf(claim, gradeRates(claim, person), floorOf(claim.getSheetId()),
180	                latenessOf(claim.getSheetId()).rounding(roundsBy(claim)));
181	    }
182	
183	    /** What is due on a claim now: its figure, plus the late charge an overdue claim has on it; none when the
184	     * figure is n/a. A settled claim's due is the figure it was settled at, the charge it had then frozen in. */
185	    public BigDecimal dueOf(Claim claim, Person person) {
186	        return dueOf(claim, gradeRates(claim, person), floorOf(claim.getSheetId()), latenessOf(claim.getSheetId()),
187	                roundsBy(claim));
188	    }
189	
190	    /** The date a claim's rounding goes by: a correction's is the date of the claim it corrects, any other's its
191	     * own. */
192	    private LocalDate roundsBy(Claim claim) {
193	        return claim.getCorrects() == null ? claim.getDate()
194	                : roundsBy(claim, datesByNumber(claims.findBySheetIdAndPersonId(claim.getSheetId(),
195	                        claim.getPersonId())));
196	    }
197	
198	    private static LocalDate roundsBy(Claim claim, Map<String, LocalDate> datesByNumber) {
199	        return claim.getCorrects() == null ? claim.getDate()
200	                : datesByNumber.getOrDefault(claim.getCorrects(), claim.getDate());
201	    }
202	
203	    /** The dates of the claims given that have a number, by number. */
204	    private static Map<String, LocalDate> datesByNumber(List<Claim> given) {
205	        Map<String, LocalDate> by = new HashMap<>();
206	        for (Claim claim : given) {
207	            if (claim.getNumber() != null) {
208	                by.put(claim.getNumber(), claim.getDate());
209	            }
210	        }
211	        return by;
212	    }
213	
214	    /**
215	     * Whether a person's due-total has a rate to go by on the sheet's today: the grade they have in force today,
216	     * or one they had on the date of a claim of theirs that counts, has a rate in force today.
217	     */
218	    public boolean rated(Person person, List<Claim> counted, LocalDate today) {
219	        return rated(person, counted, today, ratesByGrade(person.getSheetId()));
220	    }
221	
222	    private static boolean rated(Person person, List<Claim> counted, LocalDate today,
223	            Map<String, List<Rate>> byGrade) {
224	        if (today == null) {
225	            return false;
226	        }
227	        Set<String> grades = new HashSet<>();
228	        grades.add(person.gradeOn(today));
229	        for (Claim claim : counted) {
230	            grades.add(person.gradeOn(claim.getDate()));
231	        }
232	        return grades.stream().anyMatch(g -> Rate.inForce(byGrade.getOrDefault(g, List.of()), today).isPresent());
233	    }
234	
235	    /** The rates of the grade the claim's person has on the claim's date. */
236	    private List<Rate> gradeRates(Claim claim, Person person) {
237	        return rates.findBySheetIdAndGrade(claim.getSheetId(), person.gradeOn(claim.getDate()));
238	    }
239	
240	    /** The rates of the grade a person has on a date. */
241	    private static List<Rate> ratesOn(Person person, LocalDate date, Map<String, List<Rate>> byGrade) {
242	        return byGrade.getOrDefault(person.gradeOn(date), List.of());
243	    }
244	
245	    /** The sheet's rates by grade. */
246	    private Map<String, List<Rate>> ratesByGrade(String sheetId) {
247	        Map<String, List<Rate>> by = new HashMap<>();
248	        for (Rate rate : rates.findBySheetId(sheetId)) {
249	            by.computeIfAbsent(rate.getGrade(), k -> new ArrayList<>()).add(rate);
250	        }
251	        return by;
252	    }
253	
254	    private static BigDecimal dueOf(Claim claim, List<Rate> gradeRates, BigDecimal floor, Lateness late,
255	            LocalDate roundsBy) {
256	        RoundingMode rounding = late.rounding(roundsBy);
257	        BigDecimal figure = figureOf(claim, gradeRates, floor, rounding);
258	        return figure == null ? null : figure.add(lateCharge(claim, figure, late, rounding));
259	    }
260	
261	    /**
262	     * The late charge on a claim: the late percent of its figure for every full 30 days it is overdue (OPEN or
263	     * PENDING, and its due-by, fixed when it was added, before the sheet's today), rounded to two decimals as the claim rounds.
264	     * A statement never binds it: it follows the sheet's today. A correction has none.
265	     */
266	    private static BigDecimal lateCharge(Claim claim, BigDecimal figure, Lateness late, RoundingMode rounding) {
267	        if (!claim.getStatus().isOpen() || late.today() == null || claim.isCorrection()) {
268	            return BigDecimal.ZERO.setScale(2);
269	        }
270	        long overdueDays = ChronoUnit.DAYS.between(claim.getDueBy(), late.today());
271	        long periods = overdueDays > 0 ? overdueDays / LATE_PERIOD_DAYS : 0;
272	        return figure.multiply(late.latePct()).multiply(BigDecimal.valueOf(periods))
273	                .divide(BigDecimal.valueOf(100), 2, rounding);
274	    }
275	
276	    private static BigDecimal figureOf(Claim claim, List<Rate> gradeRates, BigDecimal floor, RoundingMode rounding) {
277	        if (claim.getSettledDue() != null) {
278	            return claim.getSettledDue();
279	        }
280	        return bound(claim) ? claim.getStatedDue() : liveDueOf(claim, gradeRates, floor, rounding);
281	    }
282	
283	    /** What is due on a claim at the rate its grade has in force on the claim's date, rounded to two decimals as
284	     * the claim rounds, and at least the floor (a correction has no floor); none when no rate of the grade applies
285	     * then. */
286	    private static BigDecimal liveDueOf(Claim claim, List<Rate> gradeRates, BigDecimal floor, RoundingMode rounding) {
287	        BigDecimal amount = claim.getAmount();
288	        return Rate.inForce(gradeRates, claim.getDate())
289	                .map(r -> amount.multiply(r.getRate()).divide(BigDecimal.valueOf(100), 2, rounding))
290	                .map(due -> claim.isCorrection() ? due : due.max(floor.setScale(2)))
291	                .orElse(null);
292	    }
293	
294	    private Lateness latenessOf(String sheetId) {
295	        return Lateness.of(sheets.findById(sheetId).orElse(null));
296	    }
297	
298	    /** The sheet's floor; 1.00, the one a sheet starts with, when there is no such sheet. */
299	    private BigDecimal floorOf(String sheetId) {
300	        return sheets.findById(sheetId).map(s -> s.getFloor()).orElse(new BigDecimal("1.00"));
301	    }
302	
303	    /** Whether a claim keeps a figure whatever the rates: settled at one, or bound to one (not n/a) by a
304	     * statement while not PENDING. */
305	    public static boolean keepsFigure(Claim claim) {
306	        return claim.getSettledDue() != null || (bound(claim) && claim.getStatedDue() != null);
307	    }
308	
309	    /** Whether a claim goes by the figure its person's last statement bound it to: a PENDING claim is not bound,
310	     * but shows its live figure, and is bound again if it is rejected. */
311	    private static boolean bound(Claim claim) {
312	        return claim.isStated() && claim.getStatus() != ClaimStatus.PENDING;
313	    }
314	
315	    /** Only OPEN, PENDING and SETTLED claims count toward what is claimed and due; an OPEN or PENDING one dated
316	     * within one of its person's holds does not, unless it is bound by a statement. */
317	    public static boolean counts(Claim claim, Person person) {
318	        return (claim.getStatus().isOpen() && (bound(claim) || !person.heldOn(claim.getDate())))
319	                || claim.getStatus() == ClaimStatus.SETTLED;
320	    }
321	}
