404	    /** The grade in force on a date: the one with the latest from-date on or before it. */
405	    public String gradeOn(LocalDate date) {
406	        return grades.stream()
407	                .filter(g -> g.getFrom() == null || !g.getFrom().isAfter(date))
408	                .max(GradeFrom.BY_FROM)
409	                .map(GradeFrom::getGrade)
410	                .orElseThrow();
411	    }
