413	    /** Record the grade from a from-date, replacing any the person had from that date and keeping the others. */
414	    public void setGrade(String grade, LocalDate from) {
415	        grades.removeIf(g -> Objects.equals(g.getFrom(), from));
416	        grades.add(new GradeFrom(grade, from));
417	    }
