504	        requireNameFree(sheetId, trimmed, null);
505	        Snapshot before = rollup.snapshot(sheetId);
506	        Person person = people.saveAndFlush(new Person(sheetId, trimmed, grade));
507	        audit.recordOnCommit(entry("PERSON_ADDED", user, person, sheetService.today(sheetId)));
508	        rollup.recordChanges(user, sheetId, before);
