514	     * and the save is refused if the person has been saved since. The grade is recorded from {@code gradeFrom},
515	     * the sheet's today when none is given, keeping the grades the person has from other dates.
516	     */
517	    @Transactional
518	    public Person update(String user, String sheetId, Long id, String name, String grade, LocalDate gradeFrom,
519	            Long version) {
520	        LocalDate today = sheetService.today(sheetId);
521	        Person person = people.findByIdAndSheetId(id, sheetId)
522	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
523	        if (version != null && version != person.getVersion()) {
524	            throw changedMeanwhile();
525	        }
526	        String trimmed = name.trim();
527	        requireNameFree(sheetId, trimmed, id);
528	        Snapshot before = rollup.snapshot(sheetId);
529	        person.setName(trimmed);
530	        person.setGrade(grade, gradeFrom != null ? gradeFrom : today);
531	        try {
532	            people.flush();
533	        } catch (ObjectOptimisticLockingFailureException e) {
534	            throw changedMeanwhile();
535	        }
536	        audit.recordOnCommit(entry("PERSON_EDITED", user, person, today));
537	        rollup.recordChanges(user, sheetId, before);
538	        return person;
