544	        LocalDate date = from != null ? from : sheetService.today(sheetId);
545	        Person person = people.findByIdAndSheetId(id, sheetId)
546	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
547	        person.setRetiredFrom(date);
548	        people.flush();
