554	    /** Put the person on hold from a date, the sheet's today when none is given, to a to-date or open-ended; their
555	     * OPEN and PENDING claims dated within it, unless bound by a statement, count in no live total. A to-date before
556	     * the from-date is refused. */
557	    @Transactional
558	    public Person hold(String user, String sheetId, Long id, LocalDate from, LocalDate to) {
559	        LocalDate date = from != null ? from : sheetService.today(sheetId);
560	        Person person = people.findByIdAndSheetId(id, sheetId)
561	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
562	        if (to != null && to.isBefore(date)) {
563	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "A hold cannot end before it starts.");
564	        }
565	        Snapshot before = rollup.snapshot(sheetId);
566	        person.addHold(date, to);
567	        people.flush();
568	        audit.recordOnCommit("PERSON_HELD sheet=" + sheetId + " by=" + user + " name=" + person.getName()
569	                + " from=" + date);
570	        rollup.recordChanges(user, sheetId, before);
571	        return person;
572	    }
