574	    /** Each person's patrons' ids, by person id, in the order they were named. */
575	    @Transactional(readOnly = true)
576	    public Map<Long, List<Long>> patronIds(String sheetId) {
577	        Map<Long, List<Long>> by = new LinkedHashMap<>();
578	        for (Patron patron : patrons.findBySheetIdOrderByIdAsc(sheetId)) {
579	            by.computeIfAbsent(patron.getPersonId(), k -> new ArrayList<>()).add(patron.getPatronId());
580	        }
581	        return by;
582	    }
