584	    /** Name another person on the sheet as the person's patron; refused for the person themselves and for one
585	     * already named. */
586	    @Transactional
587	    public Person addPatron(String user, String sheetId, Long id, Long patronId) {
588	        Person person = people.findByIdAndSheetId(id, sheetId)
589	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
590	        Person patron = people.findByIdAndSheetId(patronId, sheetId)
591	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such patron."));
592	        if (patron.getId().equals(person.getId())) {
593	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "A person cannot be their own patron.");
594	        }
595	        if (patrons.existsByPersonIdAndPatronId(person.getId(), patron.getId())) {
596	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That patron is already named.");
597	        }
598	        patrons.saveAndFlush(new Patron(sheetId, person.getId(), patron.getId()));
599	        audit.recordOnCommit("PATRON_ADDED sheet=" + sheetId + " by=" + user + " name=" + person.getName()
600	                + " patron=" + patron.getName());
601	        return person;
602	    }
603	
604	    /** A line naming the person and the grade they have in force on the sheet's today. */
605	    private static String entry(String event, String user, Person person, LocalDate today) {
606	        return event + " sheet=" + person.getSheetId() + " by=" + user
607	                + " name=" + person.getName() + " grade=" + person.gradeOn(today);
608	    }
609	
610	    private static ResponseStatusException changedMeanwhile() {
