615	    private void requireNameFree(String sheetId, String name, Long exceptId) {
616	        if (people.nameInUse(sheetId, name, exceptId)) {
617	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That name is already in use on this sheet.");
618	        }
