243	import net.officefloor.hq.app.rollup.RollupService.Snapshot;
244	import net.officefloor.hq.app.sheet.SheetService;
245	import org.springframework.http.HttpStatus;
246	import org.springframework.stereotype.Service;
247	import org.springframework.transaction.annotation.Transactional;
248	import org.springframework.web.server.ResponseStatusException;
249	
250	@Service
251	public class StatementService {
252	
253	    /** What a person's statements come to: how many, and the last one (none before the first). */
254	    public record Summary(int count, Statement last) {}
255	
256	    private final StatementRepository statements;
257	    private final ClaimRepository claims;
258	    private final ClaimService claimService;
259	    private final PersonRepository people;
260	    private final SheetService sheets;
261	    private final RollupService rollup;
262	    private final Audit audit;
263	
264	    public StatementService(StatementRepository statements, ClaimRepository claims, ClaimService claimService,
265	            PersonRepository people, SheetService sheets, RollupService rollup, Audit audit) {
266	        this.statements = statements;
267	        this.claims = claims;
268	        this.claimService = claimService;
269	        this.people = people;
270	        this.sheets = sheets;
271	        this.rollup = rollup;
272	        this.audit = audit;
273	    }
274	
275	    /** Each person's statements on the sheet, by person id. */
276	    @Transactional(readOnly = true)
277	    public Map<Long, Summary> summaries(String sheetId) {
278	        Map<Long, Summary> by = new HashMap<>();
279	        for (Statement s : statements.findBySheetIdOrderByIdAsc(sheetId)) {
280	            Summary was = by.get(s.getPersonId());
281	            by.put(s.getPersonId(), new Summary(was == null ? 1 : was.count() + 1, s));
282	        }
283	        return by;
284	    }
285	
286	    /**
287	     * Take a statement for a person: record their due-total now, late charges included, and bind each of their
288	     * claims that counts (OPEN and PENDING ones within a hold, unbound, do not) to the figure it has now (never its late charge, which keeps following the sheet's
289	     * today); a claim of theirs that does not count is left unbound.
290	     */
291	    @Transactional
292	    public Person take(String user, String sheetId, Long personId) {
293	        LocalDate today = sheets.today(sheetId);
294	        Person person = people.findByIdAndSheetId(personId, sheetId)
295	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
296	        Snapshot before = rollup.snapshot(sheetId);
297	        BigDecimal total = BigDecimal.ZERO.setScale(2);
298	        boolean fixed = false;
299	        List<Claim> counted = new ArrayList<>();
300	        for (Claim claim : claims.findBySheetIdAndPersonId(sheetId, personId)) {
301	            if (!RollupService.counts(claim, person)) {
302	                claim.unbind();
303	                continue;
304	            }
305	            BigDecimal figure = claimService.figureOf(claim, person);
306	            BigDecimal due = rollup.dueOf(claim, person);
307	            fixed |= RollupService.keepsFigure(claim);
308	            claim.bind(figure);
309	            counted.add(claim);
310	            if (due != null) {
311	                total = total.add(due);
312	            }
313	        }
314	        // Like the screen: with no rate in force today and no claim keeping a figure, the due-total is n/a.
315	        boolean rated = rollup.rated(person, counted, today);
316	        BigDecimal dueTotal = rated || fixed ? total : null;
317	        claims.flush();
318	        statements.saveAndFlush(new Statement(sheetId, personId, today, user, dueTotal, counted.size()));
319	        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + person.getName()
320	                + " due-total=" + (dueTotal != null ? dueTotal.toPlainString() : "n/a")
321	                + " claims=" + counted.size());
322	        rollup.recordChanges(user, sheetId, before);
323	        return person;
324	    }
325	}
