371	import java.io.IOException;
372	import java.io.UncheckedIOException;
373	import java.nio.charset.StandardCharsets;
374	import java.nio.file.Files;
375	import java.nio.file.Path;
376	import java.nio.file.StandardOpenOption;
377	import org.springframework.beans.factory.annotation.Value;
378	import org.springframework.stereotype.Service;
379	import org.springframework.transaction.support.TransactionSynchronization;
380	import org.springframework.transaction.support.TransactionSynchronizationManager;
381	
382	/**
383	 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
384	 * so tests can assert side-effects by reading that file — the second test-assertion channel
385	 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
386	 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
387	 *
388	 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
389	 * SYNC) so a test reads the record immediately.
390	 */
391	@Service
392	public class Audit {
393	
394	    private final Path file;
395	
396	    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
397	        this.file = Path.of(path);
398	    }
399	
400	    /** Append one audit record. Tests assert the exact line(s) in the file. */
401	    public synchronized void record(String entry) {
402	        try {
403	            Path parent = file.toAbsolutePath().getParent();
404	            if (parent != null) {
405	                Files.createDirectories(parent);
406	            }
407	            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
408	                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
409	        } catch (IOException e) {
410	            throw new UncheckedIOException(e);
411	        }
412	    }
413	
414	    /**
415	     * Append one audit record once the current transaction commits, so a change that is refused or
416	     * rolled back writes nothing. Outside a transaction the record is appended at once.
417	     */
418	    public void recordOnCommit(String entry) {
419	        if (!TransactionSynchronizationManager.isSynchronizationActive()) {
420	            record(entry);
421	            return;
422	        }
423	        TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization() {
424	            @Override
425	            public void afterCommit() {
426	                record(entry);
427	            }
428	        });
429	    }
430	
431	    /** Truncate the audit file. */
432	    public synchronized void clear() {
433	        try {
434	            Files.deleteIfExists(file);
435	        } catch (IOException e) {
436	            throw new UncheckedIOException(e);
437	        }
438	    }
439	}
