package net.officefloor.hq.app.statement;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.rollup.RollupService.Snapshot;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class StatementService {

    /** What a person's statements come to: how many, and the last one (none before the first). */
    public record Summary(int count, Statement last) {}

    private final StatementRepository statements;
    private final ClaimRepository claims;
    private final ClaimService claimService;
    private final PersonRepository people;
    private final SheetService sheets;
    private final RollupService rollup;
    private final Audit audit;

    public StatementService(StatementRepository statements, ClaimRepository claims, ClaimService claimService,
            PersonRepository people, SheetService sheets, RollupService rollup, Audit audit) {
        this.statements = statements;
        this.claims = claims;
        this.claimService = claimService;
        this.people = people;
        this.sheets = sheets;
        this.rollup = rollup;
        this.audit = audit;
    }

    /** Each person's statements on the sheet, by person id. */
    @Transactional(readOnly = true)
    public Map<Long, Summary> summaries(String sheetId) {
        Map<Long, Summary> by = new HashMap<>();
        for (Statement s : statements.findBySheetIdOrderByIdAsc(sheetId)) {
            Summary was = by.get(s.getPersonId());
            by.put(s.getPersonId(), new Summary(was == null ? 1 : was.count() + 1, s));
        }
        return by;
    }

    /**
     * Take a statement for a person: record their due-total now, late charges included, and bind each of their
     * claims that counts (OPEN and PENDING ones within a hold, unbound, do not) to the figure it has now (never its late charge, which keeps following the sheet's
     * today); a claim of theirs that does not count is left unbound.
     */
    @Transactional
    public Person take(String user, String sheetId, Long personId) {
        LocalDate today = sheets.today(sheetId);
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
        Snapshot before = rollup.snapshot(sheetId);
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        boolean fixed = false;
        List<Claim> counted = new ArrayList<>();
        for (Claim claim : claims.findBySheetIdAndPersonId(sheetId, personId)) {
            if (!RollupService.counts(claim, person)) {
                claim.unbind();
                continue;
            }
            BigDecimal figure = claimService.figureOf(claim, person);
            BigDecimal due = rollup.dueOf(claim, person);
            fixed |= RollupService.keepsFigure(claim);
            claim.bind(figure);
            counted.add(claim);
            if (due != null) {
                total = total.add(due);
            }
        }
        // Like the screen: with no rate in force today and no claim keeping a figure, the due-total is n/a.
        boolean rated = rollup.rated(person, counted, today);
        BigDecimal dueTotal = rated || fixed ? total : null;
        claims.flush();
        statements.saveAndFlush(new Statement(sheetId, personId, today, user, dueTotal, counted.size()));
        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + person.getName()
                + " due-total=" + (dueTotal != null ? dueTotal.toPlainString() : "n/a")
                + " claims=" + counted.size());
        rollup.recordChanges(user, sheetId, before);
        return person;
    }
}
package net.officefloor.hq.app.quickadd;

import java.math.BigDecimal;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.person.PersonService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class QuickAddService {

    /** The grade a person the quick-add creates is given. */
    static final String GRADE = "A";

    public record Added(Person person, boolean personCreated, Claim claim) {}

    private final PersonRepository people;
    private final PersonService personService;
    private final ClaimService claimService;

    public QuickAddService(PersonRepository people, PersonService personService, ClaimService claimService) {
        this.people = people;
        this.personService = personService;
        this.claimService = claimService;
    }

    /** Add a draft claim dated the sheet's today with an empty note for the named person, creating them with
     * grade A first when the name is not on the sheet. It is one change: a refused claim leaves no new person. */
    @Transactional
    public Added add(String user, String sheetId, String name, BigDecimal amount) {
        String trimmed = name.trim();
        Person person = people.findByName(sheetId, trimmed).orElse(null);
        boolean created = person == null;
        if (created) {
            person = personService.add(user, sheetId, trimmed, GRADE);
        }
        Claim claim = claimService.add(user, sheetId, person.getId(), amount, null, "", null);
        return new Added(person, created, claim);
    }
}
package net.officefloor.hq.app;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionSynchronization;
import org.springframework.transaction.support.TransactionSynchronizationManager;

/**
 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
 * so tests can assert side-effects by reading that file — the second test-assertion channel
 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
 *
 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
 * SYNC) so a test reads the record immediately.
 */
@Service
public class Audit {

    private final Path file;

    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
        this.file = Path.of(path);
    }

    /** Append one audit record. Tests assert the exact line(s) in the file. */
    public synchronized void record(String entry) {
        try {
            Path parent = file.toAbsolutePath().getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /**
     * Append one audit record once the current transaction commits, so a change that is refused or
     * rolled back writes nothing. Outside a transaction the record is appended at once.
     */
    public void recordOnCommit(String entry) {
        if (!TransactionSynchronizationManager.isSynchronizationActive()) {
            record(entry);
            return;
        }
        TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization() {
            @Override
            public void afterCommit() {
                record(entry);
            }
        });
    }

    /** Truncate the audit file. */
    public synchronized void clear() {
        try {
            Files.deleteIfExists(file);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}
